## 1️⃣ Shared Domain Types (used by all modules)

```csharp
// -----------------------------------------------------------
// SharedTypes.cs
// -----------------------------------------------------------
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace EnterpriseBlockchain.Domain
{
    // -----------------------------------------------------------------
    // Helper: SHA‑256 hashing (used for transaction and block IDs)
    // -----------------------------------------------------------------
    public static class HashHelper
    {
        public static byte[] Sha256(byte[] data)
        {
            using var sha = SHA256.Create();
            return sha.ComputeHash(data);
        }

        public static string Sha256Hex(string text) => 
            BitConverter.ToString(Sha256(Encoding.UTF8.GetBytes(text))).Replace("-", "").ToLowerInvariant();
    }

    // -----------------------------------------------------------------
    // Cryptographic keys (ECDSA – NIST P‑256, widely supported)
    // -----------------------------------------------------------------
    public sealed class CryptoKeyPair : IDisposable
    {
        public ECDsa PrivateKey { get; }
        public byte[] PublicKey { get; }

        public CryptoKeyPair()
        {
            PrivateKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
            PublicKey = PrivateKey.ExportSubjectPublicKeyInfo(); // DER‑encoded
        }

        public void Dispose() => PrivateKey?.Dispose();
    }

    // -----------------------------------------------------------------
    // Transaction model
    // -----------------------------------------------------------------
    public sealed class Transaction
    {
        public Guid Id { get; } = Guid.NewGuid();          // internal identifier
        public byte[] TxId => HashHelper.Sha256(Serialize()); // immutable hash of the payload
        public List<TxInput> Inputs { get; } = new();
        public List<TxOutput> Outputs { get; } = new();
        public byte[] Signature { get; private set; } = Array.Empty<byte>();

        // -----------------------------------------------------------------
        // Serialize only the data that is signed (inputs + outputs)
        // -----------------------------------------------------------------
        private byte[] Serialize()
        {
            var sb = new StringBuilder();
            foreach (var i in Inputs)
                sb.Append($"{i.PreviousTxId}:{i.OutputIndex};");
            foreach (var o in Outputs)
                sb.Append($"{Convert.ToBase64String(o.RecipientPubKey)}:{o.Amount};");
            return Encoding.UTF8.GetBytes(sb.ToString());
        }

        // -----------------------------------------------------------------
        // Sign with the private key that owns all inputs (simplified: 1‑to‑1)
        // -----------------------------------------------------------------
        public void Sign(ECDsa privateKey)
        {
            var data = Serialize();
            Signature = privateKey.SignData(data, HashAlgorithmName.SHA256);
        }

        // -----------------------------------------------------------------
        // Verify signature against the *first* input's public key (simplified)
        // -----------------------------------------------------------------
        public bool VerifySignature()
        {
            if (Inputs.Count == 0) return false;
            var pubKey = Inputs[0].PrevOutput?.RecipientPubKey;
            if (pubKey == null) return false;

            using var ecdsa = ECDsa.Create();
            ecdsa.ImportSubjectPublicKeyInfo(pubKey, out _);
            return ecdsa.VerifyData(Serialize(), Signature, HashAlgorithmName.SHA256);
        }
    }

    // -----------------------------------------------------------------
    // Transaction input – references a previous output (UTXO)
    // -----------------------------------------------------------------
    public sealed class TxInput
    {
        public Guid PreviousTxId { get; }
        public int OutputIndex { get; }
        public TxOutput? PrevOutput { get; set; }   // populated only during validation

        public TxInput(Guid prevTxId, int outputIndex)
        {
            PreviousTxId = prevTxId;
            OutputIndex = outputIndex;
        }
    }

    // -----------------------------------------------------------------
    // Transaction output – defines a new UTXO
    // -----------------------------------------------------------------
    public sealed class TxOutput
    {
        public decimal Amount { get; }
        public byte[] RecipientPubKey { get; } // DER‑encoded public key

        public TxOutput(decimal amount, byte[] recipientPubKey)
        {
            Amount = amount;
            RecipientPubKey = recipientPubKey;
        }
    }

    // -----------------------------------------------------------------
    // Unspent Transaction Output set – in‑memory, thread‑safe dictionary
    // -----------------------------------------------------------------
    public sealed class UTXOSet
    {
        // Key: TxId + OutputIndex (concatenated as string)
        private readonly Dictionary<string, TxOutput> _map = new();
        private readonly object _lock = new();

        private static string MakeKey(Guid txId, int index) => $"{txId}:{index}";

        public void Add(Guid txId, int index, TxOutput output)
        {
            lock (_lock)
                _map[MakeKey(txId, index)] = output;
        }

        public bool TryGet(Guid txId, int index, out TxOutput? output)
        {
            lock (_lock)
                return _map.TryGetValue(MakeKey(txId, index), out output);
        }

        public bool Spend(Guid txId, int index)
        {
            lock (_lock)
                return _map.Remove(MakeKey(txId, index));
        }

        // For snapshotting/validation
        public IReadOnlyDictionary<string, TxOutput> Snapshot()
        {
            lock (_lock)
                return new Dictionary<string, TxOutput>(_map);
        }
    }

    // -----------------------------------------------------------------
    // Block model (simplified – no Merkle tree, just raw TxIds)
    // -----------------------------------------------------------------
    public sealed class Block
    {
        public BlockHeader Header { get; }
        public List<Transaction> Transactions { get; } = new();

        public Block(BlockHeader header) => Header = header;
    }

    public sealed class BlockHeader
    {
        public int Version { get; set; } = 1;
        public byte[] PreviousBlockHash { get; set; } = Array.Empty<byte>();
        public long Timestamp { get; set; } = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        public int Nonce { get; set; } = 0;
        public int Difficulty { get; set; } = 4; // leading zero bits

        // Hash of the header (excluding the Nonce – used for PoW)
        public byte[] ComputeHash()
        {
            var sb = new StringBuilder();
            sb.Append(Version);
            sb.Append(Convert.ToBase64String(PreviousBlockHash));
            sb.Append(Timestamp);
            sb.Append(Difficulty);
            // Note: Nonce is *not* part of the hash that miners try to solve;
            // they vary it until the hash meets the difficulty.
            using var sha = SHA256.Create();
            return sha.ComputeHash(Encoding.UTF8.GetBytes(sb.ToString()));
        }

        // Full block hash (header + nonce) – what the network stores.
        public byte[] ComputeProofOfWorkHash()
        {
            var headerHash = ComputeHash();
            var combined = new byte[headerHash.Length + sizeof(int)];
            Buffer.BlockCopy(headerHash, 0, combined, 0, headerHash.Length);
            Buffer.BlockCopy(BitConverter.GetBytes(Nonce), 0, combined, headerHash.Length, sizeof(int));
            return HashHelper.Sha256(combined);
        }

        // Helper: does the PoW hash satisfy the difficulty?
        public bool IsValidProof()
        {
            var powHash = ComputeProofOfWorkHash();
            // Check leading zero bits
            int zeroBits = Difficulty;
            for (int i = 0; i < powHash.Length && zeroBits > 0; i++)
            {
                byte b = powHash[i];
                for (int bit = 7; bit >= 0 && zeroBits > 0; bit--)
                {
                    if ((b >> bit & 1) != 0) return false;
                    zeroBits--;
                }
            }
            return true;
        }
    }
}
