using System.Collections.Concurrent;
using EnterpriseBlockchain.Domain;

namespace EnterpriseBlockchain.TransactionPool
{
    public interface ITransactionPool
    {
        /// <summary>
        /// Tries to add a transaction to the pool.
        /// Returns false if the transaction is malformed, already present,
        /// or fails any validation step (signature, UTXO, double‑spend).
        /// </summary>
        bool TryAdd(Transaction tx);

        /// <summary>
        /// Returns up to `maxCount` pending transactions (FIFO order).
        /// The caller must not modify the returned list.
        /// </summary>
        IReadOnlyCollection<Transaction> GetPending(int maxCount);

        /// <summary>
        /// Removes a set of transactions that have been included in a block.
        /// </summary>
        void RemoveMined(IEnumerable<Transaction> minedTxs);
