        private readonly ConcurrentQueue<Transaction> _queue = new();
        private readonly ConcurrentDictionary<Guid, Transaction> _lookup = new(); // for fast duplicate checks
        private readonly UTXOSet _utxoSet; // shared reference with the chain validator / miner

        public TransactionPool(UTXOSet utxoSet)
        {
            _utxoSet = utxoSet ?? throw new ArgumentNullException(nameof(utxoSet));
        }

        public bool TryAdd(Transaction tx)
        {
            // 1️⃣ Basic sanity
            if (tx == null) return false;
            if (tx.Inputs.Count == 0 && tx.Outputs.Count == 0) return false;
            if (!tx.VerifySignature()) return false;

            // 2️⃣ Ensure we don't already have it
            if (!_lookup.TryAdd(tx.Id, tx))
                return false; // duplicate

            // 3️⃣ Verify that each input references an **unspent** output
            decimal totalInput = 0;
            foreach (var input in tx.Inputs)
            {
                if (!_utxoSet.TryGet(input.PreviousTxId, input.OutputIndex, out var prevOut))
                {
                    // Input does not exist or already spent
                    _lookup.TryRemove(tx.Id, out _);
                    return false;
                }

                // Attach the previous output for later fee calculation / validation
                input.PrevOutput = prevOut;
                totalInput += prevOut.Amount;
            }

            // 4️⃣ Verify output amounts and that inputs cover outputs
            decimal totalOutput = 0;
            foreach (var outp in tx.Outputs)
                totalOutput += outp.Amount;

            if (totalInput < totalOutput) // insufficient funds
            {
                _lookup.TryRemove(tx.Id, out _);
                return false;
            }

            // 5️⃣ All checks passed – enqueue for miners
            _queue.Enqueue(tx);
            return true;
        }

